  "avaliacoes": [
    {
      "id": "Ef059491884f46cf2",
      "pertinente": true,
      "tipo": "recomendacao",
      "achados": [
        {
          "proposicao": "Potes de selo, loops de selo e selos do tipo lute em cabeçotes e tanques de drenagem são usados para segregar sistemas de drenagem e para reduzir a migração de gás entre sistemas.",
          "trechos": [
            "Ef059491884f46cf2:0:687",
            "Ef059491884f46cf2:687:1385"
          ],
          "condicoes": [
            "Aplicável aos sistemas de drenagem descritos no guia de inspeção offshore",
            "A função depende da manutenção do selo líquido íntegro"
          ],
          "limites": [
            "A fonte é orientação estrangeira de inspeção, não requisito brasileiro automático",
            "O trecho não fornece método de dimensionamento, geometria, declividade nem valores de altura de selo"
          ]
        },
        {
          "proposicao": "Quando selos dependem de suprimento contínuo ou dedicado de água, a condição líquida cheia deve ser mantida; inspeções rotineiras devem verificar integridade dos selos e ausência de detritos bloqueando drenos e canaletas.",
          "trechos": [
            "Ef059491884f46cf2:0:687"
          ],
          "condicoes": [
            "Válido para arranjos de selo que utilizam água para manter a barreira líquida",
            "Depende de rotina de inspeção operacional"
          ],
          "limites": [
            "O trecho não define frequência de inspeção, critérios de aceitabilidade ou método de limpeza",
            "Não cobre desempenho em todas as arquiteturas de drenagem de FPSO"
          ]
        },
        {
          "proposicao": "Em quedas verticais, respiros ou quebra-sifão são indicados para evitar o sifonamento do líquido para fora do selo; quando há interligação direta entre vasos, o comprimento do downcomer e o ajuste de trips de baixo nível no vaso a jusante devem preservar o selo líquido e evitar refluxo entre sistemas.",
          "trechos": [
            "Ef059491884f46cf2:0:687",
            "Ef059491884f46cf2:1385:2074"
          ],
          "condicoes": [
            "Aplicável a quedas verticais e a interligações diretas entre vasos de drenagem",
            "Considera a necessidade de manter o selo sob condições operacionais previsíveis"
          ],
          "limites": [
            "A fonte não fornece comprimento mínimo, níveis de trip nem envelope operacional",
            "Trata-se de recomendação técnica/inspeção, não de comprovação experimental"
          ]
        }
      ]
    },
    {
      "id": "E02e8c3c91e09b2a1",
      "pertinente": true,
      "tipo": "recomendacao",
      "achados": [
        {
          "proposicao": "Quando houver interconexões entre sistemas de drenagem da plataforma, a segregação deve ser verificada por meio apropriado, e operações devem conseguir demonstrar como arranjos de selo permanecem cheios de líquido ao longo do tempo.",
          "trechos": [
            "E02e8c3c91e09b2a1:691:1391"
          ],
          "condicoes": [
            "Aplicável à abordagem de inspeção da fonte",
            "Depende da existência de interconexões e de arranjos de selo como barreira de segregação"
          ],
          "limites": [
            "A fonte não especifica qual meio de segregação é suficiente para cada caso",
            "Não apresenta critérios quantitativos de verificação ou projeto"
          ]
        },
        {
          "proposicao": "Para vasos de drenagem nos quais o selo líquido é essencial para prevenir migração de gás, a verificação dos níveis de alarmes e trips é tratada como meio de assegurar manutenção do selo e evitar refluxo entre sistemas.",
          "trechos": [
            "E02e8c3c91e09b2a1:0:691",
            "E02e8c3c91e09b2a1:1391:2085"
          ],
          "condicoes": [
            "Aplicável quando a filosofia do sistema depende de selo líquido no vaso",
            "Relaciona-se a prevenção de migração de gás e de fluxo reverso"
          ],
          "limites": [
            "Não há setpoints, bandas de alarme ou lógica de intertravamento no trecho",
            "A recomendação é de inspeção, não demonstra desempenho por ensaio"
          ]
        },
        {
          "proposicao": "A proteção contra congelamento por heat tracing e isolamento é tratada como estratégia para prevenir bloqueios em linhas e loops de drenagem, devendo sua efetividade ser mantida e verificada em campo.",
          "trechos": [
            "E02e8c3c91e09b2a1:0:691",
            "E02e8c3c91e09b2a1:1391:2085"
          ],
          "condicoes": [
            "Aplicável a contextos com risco de congelamento",
            "Relaciona-se especialmente a linhas de drenagem e loops de selo"
          ],
          "limites": [
            "O trecho não se aplica universalmente a climas sem risco de congelamento",
            "Não informa critérios de dimensionamento térmico nem arranjos construtivos"
          ]
        }
      ]
    },
    {
      "id": "Ebbb9e2c7b83b1913",
      "pertinente": true,
      "tipo": "explicacao_tecnica",
      "achados": [
        {
          "proposicao": "A drenagem aberta é descrita como sistema de coleta por bandejas, funis e ralos, segregada em drenagem aberta de área classificada, não classificada, drenagem de hidrocarbonetos classificada e não classificada, além de drenagem para overboard.",
          "trechos": [
            "Ebbb9e2c7b83b1913:0:698"
          ],
          "condicoes": [
            "Descrição vinculada ao arranjo recuperado no documento-fonte",
            "Abrange classificação por área e por natureza da corrente"
          ],
          "limites": [
            "A fonte não explicita critérios formais de seleção entre categorias",
            "Não informa declividades, caixas, selos, volumes ou capacidades"
          ]
        },
        {
          "proposicao": "Nos sistemas de drenagem aberta de área classificada e não classificada, o arranjo descrito inclui filtro, tanque com compartimento superior para coleta do hidrocarboneto sobrenadante e bomba vertical para envio do hidrocarboneto separado ao vaso de slop.",
          "trechos": [
            "Ebbb9e2c7b83b1913:0:698"
          ],
          "condicoes": [
            "Aplicável aos dois primeiros sistemas de drenagem aberta mencionados na fonte",
            "Pressupõe separação de fase sobrenadante antes do envio ao slop"
          ],
          "limites": [
            "O trecho não descreve mecanismo de controle de nível, prevenção de transbordamento ou selagem contra gás",
            "A origem documental é indeterminada e sem paginação identificada"
          ]
        },
        {
          "proposicao": "A drenagem fechada inclui um vaso de slop que recebe continuamente rejeito oleoso de hidrociclones e flotadores e condensado de vasos separadores, enquanto outras drenagens são descontínuas e incluem headers de equipamentos com óleo e efluente oleoso dos tanques de drenagem aberta.",
          "trechos": [
            "Ebbb9e2c7b83b1913:698:1397",
            "Ebbb9e2c7b83b1913:1397:2096"
          ],
          "condicoes": [
            "Descrição referente ao arranjo de processo apresentado na fonte",
            "Distingue correntes contínuas e descontínuas"
          ],
          "limites": [
            "Não informa filosofia de ventilação, inertização, pressão ou refluxo",
            "Não traz critérios de dimensionamento nem detalhes hidráulicos de headers"
          ]
        }
      ]
    },
    {
      "id": "Eec77726956bac748",
      "pertinente": true,
      "tipo": "explicacao_tecnica",
      "achados": [
        {
          "proposicao": "Na condição relatada, recomendou-se evitar o uso do header de fundo de bombordo para transferência de carga porque a carga migraria para o tanque slop de bombordo, admitindo-se seu uso apenas quando necessário para drenagem de tanque.",
          "trechos": [
            "Eec77726956bac748:0:698"
          ],
          "condicoes": [
            "Válido para a configuração degradada descrita, com problema de comunicação entre tanques slop",
            "Relaciona-se ao FPSO Cidade de São Mateus no contexto investigado"
          ],
          "limites": [
            "Trata-se de condição específica de incidente, não de critério geral de projeto",
            "O trecho não detalha o mecanismo hidráulico, a geometria da comunicação nem medidas definitivas de correção"
          ]
        },
        {
          "proposicao": "O esvaziamento simultâneo dos tanques slop foi seguido de alinhamento do dreno fechado de processo para o tanque 4C por mangueira flexível conectada à cow line, evidenciando alteração operacional temporária no caminho de drenagem.",
          "trechos": [
            "Eec77726956bac748:698:1392",
            "Eec77726956bac748:1392:2090"
          ],
          "condicoes": [
            "Inserido na cronologia do evento investigado",
            "Depende do contexto de indisponibilidade/problema de comunicação dos slops"
          ],
          "limites": [
            "O trecho não comprova adequação técnica dessa solução temporária",
            "Não há parâmetros para avaliar capacidade, estanqueidade, refluxo ou segurança da mangueira no uso descrito"
          ]
        }
      ]
    },
    {
      "id": "Edb623c20696a1b7f",
      "pertinente": true,
      "tipo": "explicacao_tecnica",
      "achados": [
        {
          "proposicao": "A água produzida fora de especificação era desviada para tanque próprio e reprocessada pelo separador de produção, enquanto o resquício de óleo seguia para o dreno fechado.",
          "trechos": [
            "Edb623c20696a1b7f:699:1397"
          ],
          "condicoes": [
            "Descrição do tratamento de água produzida no FPSO Frade em meados de 2011",
            "Aplicável ao cenário em que a qualidade da água não atingia a especificação esperada"
          ],
          "limites": [
            "Não informa lógica de controle, critérios analíticos de off-spec ou capacidade hidráulica",
            "Não aborda diretamente selos, caixas, declividades ou ventilação"
          ]
        },
        {
          "proposicao": "A água oleosa dos hidrociclones e o material coletado na célula de flutuação eram encaminhados por sistema de drenagem isolado para reprocessamento no separador de produção, indicando segregação funcional de correntes drenadas.",
          "trechos": [
            "Edb623c20696a1b7f:1397:2096"
          ],
          "condicoes": [
            "Descrição específica do FPSO Frade",
            "Associada ao reprocessamento dessas correntes no separador de produção"
          ],
          "limites": [
            "A fonte não explica o meio físico de isolamento nem mecanismos de prevenção de migração de gás ou refluxo",
            "Não apresenta critérios gerais para escolha dessa segregação"
          ]
        },
        {
          "proposicao": "O arranjo descrito combinava água produzida com água salgada tratada para injeção, e o vaso de injeção mantinha pressão constante para as bombas quando a água produzida caía, evitando oscilação de fluxo.",
          "trechos": [
            "Edb623c20696a1b7f:1397:2096"
          ],
          "condicoes": [
            "Aplicável ao sistema de injeção de água do FPSO Frade em 2011",
            "Especialmente na condição de queda de disponibilidade de água produzida"
          ],
          "limites": [
            "É descrição operacional do sistema de injeção, não requisito geral de drenagem",
            "O trecho não trata diretamente de funis, caixas, selos ou transbordamento"
          ]
        }
      ]
    }
